DROP TABLE IF EXISTS `hotelrooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotelrooms` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Name` varchar(100) NOT NULL,
  `RoomType` varchar(20) NOT NULL,
  `Price` decimal(12,2) NOT NULL,
  `Capacity` int NOT NULL,
  `Area` varchar(100) NOT NULL,
  `ImageUrl` varchar(500) NOT NULL,
  `Tag` varchar(50) NOT NULL,
  `Description` varchar(1000) NOT NULL,
  `BedType` varchar(50) NOT NULL,
  `HasSpa` tinyint(1) NOT NULL,
  `IsActive` tinyint(1) NOT NULL,
  PRIMARY KEY (`Id`),
  CONSTRAINT `CK_HotelRooms_BedType` CHECK ((`BedType` in (_utf8mb4'เตียงเดี่ยว',_utf8mb4'เตียงคู่'))),
  CONSTRAINT `CK_HotelRooms_Capacity` CHECK ((`Capacity` between 1 and 10)),
  CONSTRAINT `CK_HotelRooms_Price` CHECK ((`Price` > 0)),
  CONSTRAINT `CK_HotelRooms_RoomType` CHECK ((`RoomType` in (_utf8mb4'Standard',_utf8mb4'Deluxe',_utf8mb4'Suite')))
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

