--
-- Table structure for table `housekeepingtasks`
--

DROP TABLE IF EXISTS `housekeepingtasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `housekeepingtasks` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `RoomId` int NOT NULL,
  `RoomName` varchar(100) NOT NULL,
  `BookingId` int DEFAULT NULL,
  `Note` varchar(200) NOT NULL,
  `Status` varchar(20) NOT NULL,
  `CreatedAt` datetime(6) NOT NULL,
  `AssignedToUserId` int DEFAULT NULL,
  `AssignedToName` varchar(100) NOT NULL,
  `CompletedAt` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_HousekeepingTasks_Status` (`Status`),
  KEY `IX_HousekeepingTasks_RoomId_Status` (`RoomId`,`Status`),
  KEY `IX_HousekeepingTasks_BookingId` (`BookingId`),
  KEY `IX_HousekeepingTasks_AssignedToUserId` (`AssignedToUserId`),
  CONSTRAINT `FK_HousekeepingTasks_HotelBookings_BookingId` FOREIGN KEY (`BookingId`) REFERENCES `hotelbookings` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_HousekeepingTasks_HotelRooms_RoomId` FOREIGN KEY (`RoomId`) REFERENCES `hotelrooms` (`Id`) ON DELETE CASCADE,
  CONSTRAINT `FK_HousekeepingTasks_Users_AssignedToUserId` FOREIGN KEY (`AssignedToUserId`) REFERENCES `users` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `CK_HousekeepingTasks_Status` CHECK ((`Status` in (_utf8mb4'Pending',_utf8mb4'InProgress',_utf8mb4'Done')))
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

