DROP TABLE IF EXISTS `roleportals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `roleportals` (
  `Role` varchar(50) NOT NULL,
  `Port` int NOT NULL,
  `ThaiName` varchar(50) NOT NULL,
  PRIMARY KEY (`Role`),
  UNIQUE KEY `IX_RolePortals_Port` (`Port`),
  CONSTRAINT `CK_RolePortals_Port` CHECK ((`Port` between 1024 and 65535)),
  CONSTRAINT `CK_RolePortals_Role` CHECK ((`Role` in (_utf8mb4'Customer',_utf8mb4'Staff',_utf8mb4'Housekeeper',_utf8mb4'Finance',_utf8mb4'Admin',_utf8mb4'Super Admin')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
