DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Name` varchar(100) NOT NULL,
  `Email` varchar(200) NOT NULL,
  `PhoneNumber` varchar(50) NOT NULL,
  `Birthday` date NOT NULL,
  `Password` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `Role` varchar(50) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_Users_Email` (`Email`),
  KEY `IX_Users_Role` (`Role`),
  CONSTRAINT `FK_Users_RolePortals_Role` FOREIGN KEY (`Role`) REFERENCES `roleportals` (`Role`) ON DELETE RESTRICT,
  CONSTRAINT `CK_Users_Role` CHECK ((`Role` in (_utf8mb4'Customer',_utf8mb4'Staff',_utf8mb4'Housekeeper',_utf8mb4'Finance',_utf8mb4'Admin',_utf8mb4'Super Admin')))
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
